sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.food-home {
  background: #f4f8fb;
  min-height: 100vh;
  padding-bottom: 40px;
  font-family: Arial, sans-serif;
}

/* Hero */

.hero-section {
  background: linear-gradient(135deg, #1677b7, #075a75);
  padding: 55px 30px;
  text-align: center;
  color: white;
}

.hero-content h1 {
  font-size: 36px;
  margin-bottom: 12px;
  font-weight: 700;
}

.hero-content p {
  font-size: 17px;
  margin-bottom: 28px;
}

.primary-btn {
  display: inline-block;
  background: white;
  color: #075a75;
  padding: 13px 25px;
  border-radius: 6px;
  text-decoration: none;
  font-weight: bold;
}

.primary-btn:hover {
  text-decoration: none;
  opacity: 0.9;
}

/* Features */

.features-section {
  max-width: 1100px;
  margin: 40px auto;
  padding: 0 20px;
}

.features-section h2 {
  text-align: center;
  font-size: 28px;
  color: #164b60;
  margin-bottom: 5px;
}

.subtitle {
  text-align: center;
  color: #666;
  margin-bottom: 30px;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.feature-card {
  background: white;
  padding: 25px 20px;
  text-align: center;
  border-radius: 10px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.12);
  min-height: 230px;
}

.feature-card .icon {
  font-size: 38px;
  margin-bottom: 12px;
}

.feature-card h3 {
  color: #075a75;
  font-size: 19px;
}

.feature-card p {
  color: #666;
  font-size: 14px;
  line-height: 1.5;
  min-height: 55px;
}

.feature-card a {
  color: #08718c;
  font-weight: bold;
  text-decoration: none;
}

/* Information */

.info-section {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.info-box {
  background: white;
  padding: 20px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 15px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.info-box span {
  font-size: 30px;
}

.info-box h3 {
  margin: 0 0 5px;
  color: #075a75;
}

.info-box p {
  margin: 0;
  color: #666;
  font-size: 13px;
}

/* Mobile */

@media (max-width: 900px) {
  .feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .info-section {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .feature-grid {
    grid-template-columns: 1fr;
  }

  .hero-content h1 {
    font-size: 27px;
  }
}
